import {STORAGE_KEY,habitKey,validateEntry,summary,filterEntries,loadEntries} from './model.js';
const $=id=>document.getElementById(id);let entries=[],editing=null,storageError=false,timer;
function toast(message){$('toast').textContent=message;$('toast').classList.add('visible');clearTimeout(timer);timer=setTimeout(()=>$('toast').classList.remove('visible'),4500)}
try{entries=loadEntries(localStorage)}catch{storageError=true;toast('No se pudieron leer los datos guardados. No se sobrescribirán.');}
const esc=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function commit(next){if(storageError){toast('No se pueden guardar registros hasta recuperar los datos del navegador.');return false}try{localStorage.setItem(STORAGE_KEY,JSON.stringify(next));entries=next;render();return true}catch{toast('No se pudo guardar. Comprueba que el navegador permite almacenamiento local.');return false}}
function render(){const stats=summary(entries);for(const key of ['total','month','habits'])$(key).textContent=stats[key];const selected=$('habitFilter').value;const habits=[...new Map(entries.map(e=>[habitKey(e.habit),e.habit])).entries()].sort((a,b)=>a[1].localeCompare(b[1],'es'));$('habitFilter').innerHTML='<option value="">Todos los hábitos</option>'+habits.map(([key,name])=>`<option value="${esc(key)}">${esc(name)}</option>`).join('');$('habitFilter').value=habits.some(([key])=>key===selected)?selected:'';$('habitOptions').innerHTML=habits.map(([,name])=>`<option value="${esc(name)}"></option>`).join('');const visible=filterEntries(entries,$('search').value,$('habitFilter').value);$('entries').innerHTML=visible.length?visible.map(e=>`<article class="entry" data-id="${esc(e.id)}"><div class="entry-top"><div><span class="badge">${e.count} ${e.count===1?'vez':'veces'}</span><h3>${esc(e.habit)}</h3><time datetime="${esc(e.occurredAt)}">${new Intl.DateTimeFormat('es',{dateStyle:'medium',timeStyle:'short'}).format(new Date(e.occurredAt))}</time></div><div class="entry-actions"><button data-action="edit" class="secondary" aria-label="Editar registro de ${esc(e.habit)}">Editar</button><button data-action="delete" class="icon" aria-label="Eliminar registro de ${esc(e.habit)}" title="Eliminar">×</button></div></div><div class="entry-body"><div><h4>DESCRIPCIÓN</h4><p>${esc(e.description||'Sin descripción')}</p></div><div><h4>COMENTARIO / REFLEXIÓN</h4><p>${esc(e.comment||'Sin comentario')}</p></div></div></article>`).join(''):`<div class="empty"><span>↗</span><h3>${entries.length?'No hay coincidencias':'Empieza con un registro'}</h3><p>${entries.length?'Prueba otra búsqueda o cambia el filtro.':'Añade el hábito, cuántas veces ocurrió y lo que quieras recordar.'}</p>${entries.length?'':'<button class="primary" id="firstEntry">Registrar mi primera recaída</button>'}</div>`;$('firstEntry')?.addEventListener('click',()=>openForm());$('results').textContent=`${visible.length} ${visible.length===1?'registro':'registros'} · ${visible.reduce((sum,e)=>sum+e.count,0)} veces en esta vista`}
function localDateValue(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}T${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}`}
function openForm(entry){editing=entry?.id??null;$('entryForm').reset();$('dialogTitle').textContent=entry?'Editar registro':'Registrar recaída';$('occurredAt').value=localDateValue();if(entry)for(const key of ['habit','occurredAt','count','description','comment'])$(key).value=entry[key];$('entryDialog').showModal();$('habit').focus()}
$('newEntry').onclick=()=>openForm();for(const id of ['close','cancel'])$(id).onclick=()=>$('entryDialog').close();$('entryForm').onsubmit=event=>{event.preventDefault();const entry={id:editing||crypto.randomUUID(),habit:$('habit').value.trim(),occurredAt:$('occurredAt').value,count:Number($('count').value),description:$('description').value.trim(),comment:$('comment').value.trim()};const error=validateEntry(entry);if(error)return toast(error);const next=editing?entries.map(e=>e.id===editing?entry:e):[entry,...entries];if(commit(next)){$('entryDialog').close();toast(editing?'Registro actualizado':'Registro guardado')}};
$('search').oninput=render;$('habitFilter').onchange=render;$('entries').onclick=event=>{const button=event.target.closest('[data-action]');if(!button)return;const entry=entries.find(e=>e.id===button.closest('[data-id]').dataset.id);if(button.dataset.action==='edit')openForm(entry);else if(confirm(`¿Eliminar este registro de «${entry.habit}» (${entry.count} veces)?`)&&commit(entries.filter(e=>e.id!==entry.id)))toast('Registro eliminado')};
$('export').onclick=()=>{const blob=new Blob([JSON.stringify({application:'Ritmo',version:1,exportedAt:new Date().toISOString(),entries},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=`ritmo-registros-${localDateValue().slice(0,10)}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Copia de los registros exportada')};render();
